using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and data analysis." },
        new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events, societies, and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of experience teaching introductory programming courses.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an ACM Distinguished Member whose research focuses on algorithm optimization and computational complexity.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, CourseCode = "CS301", Title = "Database Systems", Description = "Comprehensive introduction to database design, SQL, normalization, transaction processing, and modern NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez spent a decade as a database architect at Oracle before joining academia. She specializes in distributed database systems.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, CourseCode = "CS401", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including supervised learning, unsupervised learning, neural networks, and practical applications.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of experience teaching introductory programming courses.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with over 20 years of experience making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research spans algebraic geometry and applied linear algebra. She has published over 40 peer-reviewed papers.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 7, CourseCode = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian methods.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with over 20 years of experience making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 8, CourseCode = "ENG101", Title = "Composition and Rhetoric", Description = "Develop critical reading and writing skills. Emphasis on argumentation, research methods, and clear academic prose.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Alice Martin", InstructorBio = "Prof. Martin is a published author and recipient of the University Teaching Excellence Award for three consecutive years.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, CourseCode = "ENG205", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and time periods. Examines themes of identity, power, and human experience.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a comparative literature scholar who has translated works from five languages and authored three books on global literary traditions.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
        new() { Id = 10, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Neil Patel", InstructorBio = "Dr. Patel is a former NASA researcher whose work on fluid dynamics in microgravity has been published in Nature and Science.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 11, CourseCode = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM + Mon Lab 3:00–5:50 PM", InstructorName = "Dr. Neil Patel", InstructorBio = "Dr. Patel is a former NASA researcher whose work on fluid dynamics in microgravity has been published in Nature and Science.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 12, CourseCode = "HIST101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural exchanges from ancient times through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Catherine Moore", InstructorBio = "Dr. Moore is an archaeologist and historian specializing in ancient Mediterranean civilizations with active excavation sites in Greece and Turkey.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
        new() { Id = 13, CourseCode = "HIST205", Title = "Modern World History", Description = "From the Age of Exploration to the present day. Examines colonialism, revolutions, world wars, and globalization.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. David Okafor", InstructorBio = "Dr. Okafor is a specialist in postcolonial history and has served as a consultant for several documentary film series.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

