@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore our departments, discover courses, and enroll for the upcoming semester.</p>
</div>

<section class="mt-4">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in FeaturedCourses)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                        <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                        <p class="card-text">@Truncate(course.Description, 100)</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section class="mt-5">
    <h2>Departments</h2>
    <div class="list-group">
        @foreach (var dept in Departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
                <strong>@dept.Code</strong> — @dept.Name
                <br /><small class="text-muted">@dept.Description</small>
            </a>
        }
    </div>
</section>

@code {
    private List<Course> FeaturedCourses { get; set; } = [];
    private List<Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        FeaturedCourses = CatalogService.GetFeaturedCourses();
        Departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@SearchTerm" class="form-control" placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (Courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @Courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in Courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private string? SearchTerm => Search;
    private List<Course> Courses { get; set; } = [];
    private List<Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        Departments = CatalogService.GetDepartments();
        Courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

